import{_ as i,l as r,o as a,c as n,v as o,p as l,x as t,d as c,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"路径查找","description":"","frontmatter":{"title":"路径查找","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/path-lookup.md","filePath":"cs/path-lookup.md","lastUpdated":1789023840000}'),h={name:"cs/path-lookup.md"};function u(m,e,_,E,f,k){const d=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="路径查找" tabindex="-1">路径查找 <a class="header-anchor" href="#路径查找" aria-label="Permalink to &quot;路径查找&quot;">​</a></h1><div class="epigraph"><p>把路径字符串拆成分量，从根或工作目录起逐级 lookup；权限在每一层目录的搜索位上检查。</p><footer>—— 据 Bach 对 namei 的叙述；POSIX 对路径名解析的整理</footer></div><p><a href="/cs/inode-dir">上一课</a>规定目录是名字到 inode 号的文件，并给出 <code>/a/b</code> 的直观走法。<a href="/cs/dcache">dcache</a> 能加速每一分量。缺口是<strong>完整算法</strong>：绝对/相对、<code>.</code> <code>..</code>、工作目录、根（chroot）、末尾斜线、以及何时跟随符号链接——链接本身下一课才展开，本课留下「遇链接则再解析」的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只说「从根 inode 读目录」不够：进程有 cwd 与 root，线程可以有不同 cwd。查找必须在每一层验证执行（搜索）权限，否则用户能靠猜 inode 号越权。缺口不是再定义 inode 字段，而是 namei 状态机：当前目录 inode、剩余分量、标志（要目录还是要文件、是否跟链接）。最后一分量对 <code>unlink</code> 与 <code>open</code> 处理不同。</p><p>本课不把 Linux 的 <code>nameidata</code> 每个标志位背完。</p><p><span class="marginnote">「。」是当前，「..」是父。越过挂载点要换超级块，那是 VFS/挂载课；本课承认查找会碰到挂载点接口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>绝对路径从进程 root 开始，相对路径从 cwd。循环：取下一分量，dcache 或目录文件 lookup，检查当前目录的搜索位。末分量按调用意图处理（必须存在 / 必须不存在 / 跟随链接）。深度与符号链接跳数有上限，防环。结果是目标 inode（或 dentry），交给 <code>open</code> 填<a href="/cs/file-table">文件表</a>。</p>',9)),(a(),l(p,null,{default:t(()=>[s(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PATH%5B%22%E8%B7%AF%E5%BE%84%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%20--%3E%20SPLIT%5B%22%E6%8B%86%E5%88%86%E9%87%8F%22%5D%0A%20%20SPLIT%20--%3E%20CUR%5B%22%E4%BB%8E%20root%20%E6%88%96%20cwd%22%5D%0A%20%20CUR%20--%3E%20LOOK%5B%22lookup%20%2B%20%E6%90%9C%E6%9D%83%22%5D%0A%20%20LOOK%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E5%88%86%E9%87%8F%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>路径查找把「用户看见的树」变成 inode 号序列，是一切按名系统调用的共同前缀。它不搬文件数据页——那是页 Cache。权限沿路径每一目录检查，最后才看目标的读/写位，这解释了为何对目录没有 x 就不能打开其下文件。不要把查找写成安全课的提权步骤；只讲检查点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>openat</code> 相对任意 fd 的全部细节，只承认「起点可以不是 cwd」。不把 Unicode 正规化当内核默认。硬链接与符号链接在下一课改变「名与对象」；本课的 lookup 假定分量要么是目录项要么失败。</p><p>后课默认：分量级 lookup 已有。两个名字对着同一 inode，或一个名字存着另一条路径，下一课硬链接与符号链接。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>namei 从 root/cwd 逐分量 lookup，并检查目录搜索位。</li><li>末分量语义随系统调用而变。</li><li>链接如何改写解析，是下一课。</li><li>出处：Bach, <em>UNIX</em>；POSIX pathname resolution；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const P=i(h,[["render",u]]);export{T as __pageData,P as default};
